import {evaluated} from '../animation/evaluate.js';
import {matrix} from '../scene/matrix.js';
export const NS='http://www.w3.org/2000/svg';
export const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function pathData(n){if(n.rawPath)return n.rawPath;const pts=n.nodes;if(!pts.length)return '';let d=`M ${pts[0].x} ${pts[0].y}`;const segment=(a,b)=>a.out||b.in?` C ${(a.out||a).x} ${(a.out||a).y} ${(b.in||b).x} ${(b.in||b).y} ${b.x} ${b.y}`:` L ${b.x} ${b.y}`;for(let i=1;i<pts.length;i++)d+=segment(pts[i-1],pts[i]);if(n.closed&&pts.length>1)d+=segment(pts.at(-1),pts[0])+' Z';return d;}
export function artwork(n,time,interactive=false,inheritedLock=false){if(!n.visible)return '';const v=evaluated(n,time),m=matrix(v);let body='';if(n.type==='group')body=n.children.map(c=>artwork(c,time,interactive,inheritedLock||n.locked)).join('');else if(n.type==='rectangle')body=`<rect width="${v.width}" height="${v.height}" rx="${v.radius||0}"/>`;else if(n.type==='ellipse')body=`<ellipse cx="${v.width/2}" cy="${v.height/2}" rx="${v.width/2}" ry="${v.height/2}"/>`;else if(n.type==='text')body=`<text x="${v.align==='center'?v.width/2:v.align==='right'?v.width:0}" y="${v.fontSize}" font-family="${escape(v.font)}" font-size="${v.fontSize}" text-anchor="${v.align==='center'?'middle':v.align==='right'?'end':'start'}">${escape(v.text)}</text>`;else body=`<path d="${escape(pathData(v))}" stroke-linecap="round" stroke-linejoin="round"/>`;return `<g ${interactive?`data-id="${n.id}" style="pointer-events:${inheritedLock||n.locked?'none':'auto'}"`:''} transform="matrix(${m.join(' ')})" opacity="${v.opacity}" fill="${escape(v.fill)}" stroke="${escape(v.stroke)}" stroke-width="${v.strokeWidth}">${body}</g>`;}
export function sceneSVG(p,time,ids){const prune=n=>ids.includes(n.id)?n:{...n,children:(n.children||[]).map(prune).filter(Boolean),type:'group'};const keep=n=>ids.includes(n.id)||n.children?.some(keep);const nodes=ids?p.layers.filter(keep).map(prune):p.layers;return `<svg xmlns="${NS}" width="${p.width}" height="${p.height}" viewBox="0 0 ${p.width} ${p.height}"><rect width="100%" height="100%" fill="${escape(p.background)}"/>${nodes.map(n=>artwork(n,time)).join('')}</svg>`;}
export class PreviewRenderer{constructor(svg){this.svg=svg;this.cache='';}render(p,time){const markup=`<rect class="stage-paper" width="${p.width}" height="${p.height}" fill="${escape(p.background)}"/>${p.layers.map(n=>artwork(n,time,true)).join('')}`;this.svg.setAttribute('viewBox',`0 0 ${p.width} ${p.height}`);if(markup!==this.cache){const template=document.createElementNS(NS,'svg');template.innerHTML=markup;const patch=(current,next)=>{if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){current.replaceWith(next.cloneNode(true));return;}if(current.nodeType===3){if(current.textContent!==next.textContent)current.textContent=next.textContent;return;}for(const attr of [...current.attributes])if(!next.hasAttribute(attr.name))current.removeAttribute(attr.name);for(const attr of [...next.attributes])if(current.getAttribute(attr.name)!==attr.value)current.setAttribute(attr.name,attr.value);const a=[...current.childNodes],b=[...next.childNodes];for(let i=0;i<Math.max(a.length,b.length);i++){if(!a[i])current.appendChild(b[i].cloneNode(true));else if(!b[i])a[i].remove();else patch(a[i],b[i]);}};const a=[...this.svg.childNodes],b=[...template.childNodes];for(let i=0;i<Math.max(a.length,b.length);i++){if(!a[i])this.svg.appendChild(b[i].cloneNode(true));else if(!b[i])a[i].remove();else patch(a[i],b[i]);}this.cache=markup;}}}
